"""Isolated transport/serialization boundaries; generated bytes are not observations."""
from dataclasses import replace
import hashlib
import time
from threading import Barrier, Event

import httpx
import pytest

from core.config import settings
from services import irsa_client as irsa


def artifact():
    return irsa.ArtifactRecord("ibe/data/spherex/dr1/level2/unit.fits", 60000, 60001,
                               1, "SPHEREx-D1", "unit", "DR1", "spherex_dr1")


@pytest.mark.parametrize("allow_partial", [False, True])
def test_download_stage_preserves_completed_inputs_and_freezes_receipts(tmp_path, monkeypatch, allow_partial):
    release = Event()
    finished = Event()
    first = artifact()
    second = replace(first, uri="ibe/data/spherex/dr1/level2/late-unit.fits")
    total_deadline = time.monotonic() + 10
    stage_deadline = time.monotonic() + .15
    client = irsa.IrsaClient(replace(settings, cache_dir=tmp_path),
                             deadline_at=total_deadline, use_cache=False)
    children = []

    def fake_fetch(child, record, ra, dec, size):
        children.append(child)
        assert child is not client and child.deadline_at == stage_deadline
        assert child.use_cache is False
        if record == second:
            release.wait(2)
        child.acquisition_metadata.append({"source_url": record.cutout_url(ra, dec, size),
                                            "sha256": "test-only", "outcome": "test_receipt"})
        if record == second:
            finished.set()
        return b"isolated transport test bytes, not observations"

    monkeypatch.setattr(irsa.IrsaClient, "fetch_cutout", fake_fetch)
    try:
        if allow_partial:
            result = client.fetch_cutouts([first, second], 1, 2, .2,
                                          stage_deadline_at=stage_deadline, allow_partial=True)
            assert list(result) == [first]
        else:
            with pytest.raises(irsa.IRSAUnavailable, match="deadline"):
                client.fetch_cutouts([first, second], 1, 2, .2, stage_deadline_at=stage_deadline)
        assert client.deadline_at == total_deadline
        assert client.download_metadata["completed_count"] == 1
        assert client.download_metadata["status"] == "partial"
        assert client.acquisition_metadata[-1]["outcome"] == "stage_deadline_exhausted"
        snapshot = list(client.acquisition_metadata)
        release.set()
        assert finished.wait(1)
        assert client.acquisition_metadata == snapshot
        assert all(child is children[0] for child in children)
    finally:
        release.set()


def test_partial_download_stage_never_returns_empty_as_success(tmp_path, monkeypatch):
    client = irsa.IrsaClient(replace(settings, cache_dir=tmp_path))
    monkeypatch.setattr(irsa.IrsaClient, "fetch_cutout", lambda *args, **kwargs: pytest.fail("expired stage contacted upstream"))
    with pytest.raises(irsa.IRSAUnavailable, match="deadline"):
        client.fetch_cutouts([artifact()], 1, 2, .2, stage_deadline_at=time.monotonic()-1,
                             allow_partial=True)
    assert client.download_metadata["completed_count"] == 0
    assert client.download_metadata["status"] == "failed"


def test_complete_download_stage_and_total_deadline_minimum(tmp_path, monkeypatch):
    deadline = time.monotonic()+10
    client = irsa.IrsaClient(replace(settings, cache_dir=tmp_path), deadline_at=deadline)
    def fake_fetch(child, *args):
        assert child.deadline_at == deadline
        return b"isolated transport test"
    monkeypatch.setattr(irsa.IrsaClient, "fetch_cutout", fake_fetch)
    assert client.fetch_cutouts([artifact()], 1, 2, .2, stage_deadline_at=deadline+20) == {
        artifact(): b"isolated transport test"}
    assert client.download_metadata["status"] == "complete"
    assert client.download_metadata["failed_inputs"] == []
    assert client.fetch_cutouts([], 1, 2, .2, allow_partial=True) == {}


def test_partial_download_all_failed_is_upstream_failure(tmp_path, monkeypatch):
    client = irsa.IrsaClient(replace(settings, cache_dir=tmp_path))
    def unavailable(*args):
        raise irsa.IRSAUnavailable("isolated test upstream outage")
    monkeypatch.setattr(irsa.IrsaClient, "fetch_cutout", unavailable)
    with pytest.raises(irsa.IRSAUnavailable, match="All cutout downloads failed"):
        client.fetch_cutouts([artifact()], 1, 2, .2, stage_deadline_at=time.monotonic()+10,
                             allow_partial=True)
    assert client.download_metadata["status"] == "failed"
    assert client.download_metadata["stage_deadline_exhausted"] is False


def test_complete_sia_is_primary_and_does_not_wait_for_tap(tmp_path, monkeypatch):
    client = irsa.IrsaClient(replace(settings, cache_dir=tmp_path), deadline_at=time.monotonic()+30)
    monkeypatch.setattr(client, "sia2_query", lambda *args, **kwargs: [artifact()])
    def no_tap(*args, **kwargs):
        pytest.fail("Successful complete SIA must not spend the remaining budget on TAP")
    monkeypatch.setattr(client, "tap_query", no_tap)
    assert client.query_artifacts(1,2) == [artifact()]


def test_incomplete_sia_uses_complete_tap_without_resetting_budget(tmp_path, monkeypatch):
    deadline = time.monotonic()+30
    client = irsa.IrsaClient(replace(settings, cache_dir=tmp_path), deadline_at=deadline)
    def incomplete(*args, **kwargs):
        raise irsa.IRSAUnavailable("one requested collection failed")
    monkeypatch.setattr(client, "sia2_query", incomplete)
    def tap(*args, **kwargs):
        assert client.deadline_at == deadline
        return [artifact()]
    monkeypatch.setattr(client, "tap_query", tap)
    assert client.query_artifacts(1,2) == [artifact()]


def test_both_discovery_failures_never_become_no_data(tmp_path, monkeypatch):
    client = irsa.IrsaClient(replace(settings, cache_dir=tmp_path))
    def outage(*args, **kwargs):
        raise irsa.IRSAUnavailable("actual outage")
    monkeypatch.setattr(client, "sia2_query", outage)
    monkeypatch.setattr(client, "tap_query", outage)
    with pytest.raises(irsa.IRSAUnavailable, match="incomplete"):
        client.query_artifacts(1,2)
    assert client.discovery_metadata["status"] == "incomplete"


def test_fresh_mode_bypasses_valid_cache_and_records_receipt(tmp_path, monkeypatch):
    client = irsa.IrsaClient(replace(settings, cache_dir=tmp_path, retries=1), use_cache=False)
    record = artifact()
    old = b"SIMPLE" + b"0"*3000
    new = b"SIMPLE" + b"1"*3000
    path = client._cutout_cache_path(record,1,2,.2)
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_bytes(old)
    contacted=[]
    def handler(request):
        contacted.append(request)
        return httpx.Response(200, content=new)
    monkeypatch.setattr(client,"_new_client",lambda:httpx.Client(transport=httpx.MockTransport(handler)))
    assert client.fetch_cutout(record,1,2,.2) == new
    assert len(contacted)==1 and path.read_bytes()==new
    receipt=client.acquisition_metadata[-1]
    assert receipt["from_cache"] is False and receipt["retrieved_at"] is not None
    assert receipt["sha256"]==hashlib.sha256(new).hexdigest()
    cached = irsa.IrsaClient(replace(settings,cache_dir=tmp_path))
    monkeypatch.setattr(cached,"_new_client",lambda:pytest.fail("Default legacy cache read must not download"))
    assert cached.fetch_cutout(record,1,2,.2)==new
    assert cached.acquisition_metadata[-1]["retrieved_at"] is None
    assert cached.acquisition_metadata[-1]["from_cache"] is True


@pytest.mark.parametrize("ra,dec", [(359.9999999,90),(359.9999999,-90),(360,0),(0,89.9999999)])
def test_cutout_serialization_wraps_without_invalid_coordinates(ra,dec):
    wrapped,latitude=irsa.canonical_cutout_position(ra,dec)
    assert 0<=wrapped<360 and -90<=latitude<=90
    assert "center=360." not in artifact().cutout_url(ra,dec,.2)


def test_query_position_wrap_and_raw_response_retention(tmp_path, monkeypatch):
    empty=(b'<VOTABLE version="1.3" xmlns="http://www.ivoa.net/xml/VOTable/v1.3">'
           b'<RESOURCE type="results"><INFO name="QUERY_STATUS" value="OK"/>'
           b'<TABLE><FIELD name="access_url" datatype="char" arraysize="*"/>'
           b'<DATA><TABLEDATA/></DATA></TABLE></RESOURCE></VOTABLE>')
    seen=[]
    def handler(request):
        seen.append(dict(request.url.params))
        return httpx.Response(200,content=empty)
    client=irsa.IrsaClient(replace(settings,cache_dir=tmp_path,retries=1))
    monkeypatch.setattr(client,"_new_client",lambda:httpx.Client(transport=httpx.MockTransport(handler)))
    assert client.sia2_query(359.999999999,90)==[]
    assert len(seen)==4 and all(item["POS"]=="circle 0.00000000 90.00000000 0.000000" for item in seen)
    assert client.discovery_metadata["query"]["ra"]==359.999999999
    assert client.discovery_metadata["status"]=="complete"
    for receipt in client.discovery_metadata["responses"]:
        assert (tmp_path/receipt["cache_relative_path"]).read_bytes()==empty
        assert receipt["sha256"]==hashlib.sha256(empty).hexdigest()
        assert receipt["http_status"]==200 and receipt["retrieved_at"]


def sia_table(*, overflow=False):
    status=b'<INFO name="QUERY_STATUS" value="OVERFLOW"/>' if overflow else b''
    return (b'<VOTABLE version="1.3" xmlns="http://www.ivoa.net/xml/VOTable/v1.3"><RESOURCE type="results">'
            b'<INFO name="QUERY_STATUS" value="OK"/><TABLE>'
            b'<FIELD name="access_url" datatype="char" arraysize="*"/>'
            b'<FIELD name="energy_bandpassname" datatype="char" arraysize="*"/>'
            b'<FIELD name="t_min" datatype="double"/><DATA><TABLEDATA><TR>'
            b'<TD>https://irsa.ipac.caltech.edu/ibe/data/spherex/dr1/level2/unit.fits</TD>'
            b'<TD>SPHEREx-D1</TD><TD>60000</TD></TR></TABLEDATA></DATA></TABLE>'+status+b'</RESOURCE></VOTABLE>')


def test_parallel_collections_start_together_and_explicit_partial_omits_overflow(tmp_path, monkeypatch):
    barrier=Barrier(4)
    def handler(request):
        collection=request.url.params['COLLECTION']
        barrier.wait(timeout=3)
        if collection=='spherex_dr1':
            return httpx.Response(200,content=sia_table())
        if collection=='spherex_qr3':
            return httpx.Response(200,content=sia_table(overflow=True))
        return httpx.Response(502,content=b'upstream unavailable')
    client=irsa.IrsaClient(replace(settings,cache_dir=tmp_path,retries=1),deadline_at=time.monotonic()+15)
    monkeypatch.setattr(client,'_new_client',lambda:httpx.Client(transport=httpx.MockTransport(handler)))
    monkeypatch.setattr(client,'tap_query',lambda *args,**kwargs:pytest.fail('Explicit nonempty partial should preserve download budget'))
    records=client.query_artifacts(1,2,allow_partial=True)
    assert len(records)==1
    assert client.discovery_metadata['status']=='partial'
    assert client.discovery_metadata['missing_collections']==['spherex_qr3','spherex_dr1_deep','spherex_qr3_deep']
    assert len(client.discovery_metadata['responses'])==4


def test_partial_empty_remains_an_upstream_error(tmp_path,monkeypatch):
    client=irsa.IrsaClient(replace(settings,cache_dir=tmp_path,retries=1))
    def partial(*args,**kwargs):
        raise irsa.IRSAIncompleteDiscovery('incomplete',records=[],missing_collections=['spherex_dr1'])
    def failed_tap(*args,**kwargs):
        raise irsa.IRSAUnavailable('TAP unavailable')
    monkeypatch.setattr(client,'sia2_query',partial)
    monkeypatch.setattr(client,'tap_query',failed_tap)
    with pytest.raises(irsa.IRSAUnavailable):
        client.query_artifacts(1,2,allow_partial=True)


