def test_parallel_discovery_deadline_does_not_wait_for_stalled_workers(tmp_path,monkeypatch):
    release=Event()
    client=irsa.IrsaClient(replace(settings,cache_dir=tmp_path,retries=1),deadline_at=time.monotonic()+.12)
    def stalled(*args,**kwargs):
        release.wait(.8)
        raise irsa.IRSAUnavailable('stalled request finished')
    monkeypatch.setattr(client,'_request',stalled)
    started=time.monotonic()
    try:
        with pytest.raises(irsa.IRSAIncompleteDiscovery):
            client.sia2_query(1,2,parallel=True)
        assert time.monotonic()-started < .5
    finally:
        release.set()
